describe('repro', () => {
  it('two multiline texts', () => {
    FabricObject.ownDefaults.objectCaching = true;
    const canvas = new StaticCanvas(undefined, { width: 400, height: 400 });
    const t1 = new FabricText('multi line\ntext here\nthird line', { fontSize: 20, left: 40, top: 40 });
    const t2 = new FabricText('another one\nsecond line\nthird', { fontSize: 20, left: 200, top: 200 });
