import { describe, it } from 'vitest';
import { StaticCanvas, FabricText } from '../fabric';

describe('repro', () => {
  it('two multiline texts', () => {
    const canvas = new StaticCanvas(undefined, { width: 400, height: 400 });
    const t1 = new FabricText('a\nb', { left: 50, top: 50, fontSize: 40 });
    const t2 = new FabricText('c\nd', { left: 200, top: 50, fontSize: 40 });
    canvas.add(t1, t2);
    canvas.renderAll();
    console.log('T1', { left: t1.left, top: t1.top, width: t1.width, height: t1.height });
    console.log('T2', { left: t2.left, top: t2.top, width: t2.width, height: t2.height });
    console.log('T1 aCoords', JSON.stringify(t1.aCoords));
    console.log('T2 aCoords', JSON.stringify(t2.aCoords));
    console.log('T1 matrix', JSON.stringify(t1.calcTransformMatrix()));
    console.log('T2 matrix', JSON.stringify(t2.calcTransformMatrix()));
  });
});

