3	import { FabricError } from '../internals/console';
4	/**
5	 * Creates canvas element
6	 * @return {CanvasElement} initialized canvas element
7	 */
8	export const createCanvasElement = (): HTMLCanvasElement => {
9	  const element = getFabricDocument().createElement('canvas');
10	  if (!element || typeof element.getContext === 'undefined') {
11	    throw new FabricError('Failed to create `canvas` element');
12	  }
13	  return element;
14	};
15	
16	/**
17	 * Creates image element (works on client and node)
18	 * @return {HTMLImageElement} HTML image element
19	 */
20	export const createImage = (): HTMLImageElement =>
21	  getFabricDocument().createElement('img');
22	
23	/**
24	 * Creates a canvas element that is a copy of another and is also painted
25	 * @param {CanvasElement} canvas to copy size and content of
26	 * @return {CanvasElement} initialized canvas element
27	 */
28	export const copyCanvasElement = (
29	  canvas: HTMLCanvasElement,
30	): HTMLCanvasElement => {
31	  const newCanvas = createCanvasElementFor(canvas);
32	  newCanvas.getContext('2d')?.drawImage(canvas, 0, 0);
33	  return newCanvas;
34	};
35	
36	/**
37	 * Creates a canvas element as big as another
38	 * @param {CanvasElement} canvas to copy size and content of
39	 * @return {CanvasElement} initialized canvas element
40	 */
41	export const createCanvasElementFor = (
42	  canvas: HTMLCanvasElement | ImageData | HTMLImageElement | TSize,
43	): HTMLCanvasElement => {
44	  const newCanvas = createCanvasElement();
45	  newCanvas.width = canvas.width;
46	  newCanvas.height = canvas.height;
47	  return newCanvas;
48	};
