import { StaticCanvas, Textbox, FabricText } from './dist/index.node.mjs';
import { createCanvas, loadImage } from 'canvas';
import fs from 'fs';
const save=(c,n)=>fs.writeFileSync(`/app/${n}`,Buffer.from(c.toDataURL().split(',')[1],'base64'));
async function analyze(name){const img=await loadImage(`/app/${name}`);const c=createCanvas(img.width,img.height);const x=c.getContext('2d');x.drawImage(img,0,0);const d=x.getImageData(0,0,img.width,img.height).data;let dark=0,minX=1e9,maxX=-1,minY=1e9,maxY=-1;for(let y=0;y<img.height;y++)for(let X=0;X<img.width;X++){const i=(y*img.width+X)*4;if(d[i+3]>10&&(d[i]+d[i+1]+d[i+2])/3<200){dark++;minX=Math.min(minX,X);maxX=Math.max(maxX,X);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}}console.log('  ',name,`dark=${dark} x[${minX},${maxX}] y[${minY},${maxY}]`);}

const canvas=new StaticCanvas(undefined,{width:400,height:300});
const t1=new FabricText('Hello\nWorld',{left:20,top:20,fontSize:40,lineHeight:1.16});
